function metadata(title,description,path,image,structured){return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)} | Elvarins</title><meta name="description" content="${escape(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="https://elvarins.com${escape(path)}"><meta property="og:type" content="product"><meta property="og:title" content="${escape(title)} | Elvarins"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="https://elvarins.com${escape(path)}"><meta property="og:image" content="${escape(image)}"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#15264a"><link rel="icon" type="image/png" sizes="96x96" href="/favicon.png?v=retail-20261010"><link rel="icon" type="image/svg+xml" href="/logo.svg?v=retail-20261010"><link rel="stylesheet" href="/style.css"><link rel="preconnect" href="https://media.entertainmentearth.com"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><script type="application/ld+json">${json(structured)}</script></head><body>`;}
function card(p){return `<article class="product-card" data-sku="${escape(p.sku)}" data-collection="${escape(p.collection)}"><a class="product-photo" href="${escape(p.url)}"><img src="${escape(p.image)}" alt="${escape(p.title)}" width="500" height="500" loading="lazy" decoding="async" referrerpolicy="no-referrer"></a><div class="product-copy"><span class="brand">${escape(p.brand)}</span><h3><a href="${escape(p.url)}">${escape(p.title)}</a></h3><span class="unit">1 packaged item</span><div class="product-bottom"><span class="price">$${p.price.toFixed(2)} <small>USD</small></span><button class="product-action" type="button" data-product="${escape(p.sku)}" aria-label="Quick view ${escape(p.title)}">Quick view ↗</button></div></div></article>`;}
export function renderProduct(p){
 const collection=collections.find(c=>c.slug===p.collection),related=products.filter(x=>x.collection===p.collection&&x.sku!==p.sku).slice(0,3);
 const breadcrumb={'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:'https://elvarins.com/'},{'@type':'ListItem',position:2,name:collection.name,item:'https://elvarins.com/collections/'+collection.slug},{'@type':'ListItem',position:3,name:p.title,item:'https://elvarins.com'+p.url}]};
 const structured={'@context':'https://schema.org','@graph':[{'@type':'Product','@id':'https://elvarins.com'+p.url+'#product',name:p.title,sku:p.sku,description:p.description,image:[...new Set([p.image,...(p.images||[])])],url:'https://elvarins.com'+p.url,category:p.productType,...(p.gtin12?{gtin12:p.gtin12,mpn:p.manufacturerSku}:{}),brand:{'@type':'Brand',name:p.brand}},breadcrumb]};
 return metadata(p.title,p.description,p.url,p.image,structured)+chrome.header.replace('class="skip" href="/#shop"','class="skip" href="#product-main"')+`<main class="product-page" id="product-main"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><a href="/collections/${escape(collection.slug)}">${escape(collection.name)}</a><span aria-hidden="true">/</span><span>${escape(p.sku)}</span></nav><div class="detail-grid"><div class="detail-photo" data-collection="${escape(p.collection)}" data-product-gallery><div><img data-gallery-image src="${escape(p.image)}" alt="${escape(p.title)}" width="500" height="500" fetchpriority="high" referrerpolicy="no-referrer"><div class="gallery-thumbs" data-gallery-thumbs hidden></div><p class="gallery-status" data-gallery-status aria-live="polite"></p><a data-gallery-zoom class="zoom-link" href="${escape(p.image)}" target="_blank" rel="noopener noreferrer">Open full-size photo ↗</a></div></div><div class="detail-copy"><span class="brand">${escape(p.brand)}</span><h1>${escape(p.title)}</h1><span class="price">$${p.price.toFixed(2)} <small>USD</small></span><p class="description">${escape(p.description)}</p>${p.safetyNote?'<p class="detail-note">'+escape(p.safetyNote)+'</p>':''}<dl><dt>Brand</dt><dd>${escape(p.brand)}</dd><dt>Item number</dt><dd>${escape(p.sku)}</dd><dt>Product type</dt><dd>${escape(p.productType)}</dd>${p.size?`<dt>Item size</dt><dd>${escape(p.size)}</dd>`:''}<dt>Package contents</dt><dd>1 original packaged item</dd></dl><form id="shipping-form" class="shipping-form"><label for="shipping-qty">Quantity</label><input id="shipping-qty" type="number" min="1" max="20" value="1" required><p id="item-subtotal"></p><label for="shipping-zip">U.S. delivery ZIP code</label><input id="shipping-zip" inputmode="numeric" autocomplete="postal-code" pattern="[0-9]{5}(-[0-9]{4})?" maxlength="10" placeholder="e.g. 10001" required><button class="btn btn-primary" type="submit" id="shipping-submit">Check shipping</button><p id="shipping-result" role="status" aria-live="polite">Shipping is confirmed before purchase. It is not included in the item price.</p></form><button id="detail-inquiry" class="btn btn-primary" type="button" data-product-question>Request purchase details →</button><p class="detail-note">Contact us to confirm availability, shipping and any applicable taxes before purchase. Your inquiry does not place an order. Online checkout is not yet enabled.</p><div class="detail-help"><a href="/shipping-delivery">U.S. shipping · 1–2 business day processing</a><a href="/returns">30-day return policy · conditions apply</a></div></div></div><section class="related-products" aria-labelledby="related-title"><h2 id="related-title">More from ${escape(collection.name)}</h2><div class="product-grid">${related.map(p=>card(p).replace(/<button class="product-action"[\s\S]*?<\/button>/,`<a class="product-action" href="${escape(p.url)}">View item ↗</a>`)).join('')}</div><p><a href="/collections/${escape(collection.slug)}">Explore the collection →</a></p></section></main>`+chrome.footer+customerUI+`<script src="/retail.js" defer></script><script id="product-data" type="application/json">${json(p)}</script><script src="/gallery.js" defer></script><script src="/product.js" defer></script></body></html>`;
}
export function renderCollection(slug,homepage){
 const c=collections.find(c=>c.slug===slug);if(!c)return null;const subset=products.filter(p=>p.collection===slug);
 let page=homepage.replace(/<title>.*?<\/title>/,`<title>${escape(c.name)} | Elvarins</title>`).replace(/(<meta name="description" content=")[^"]*(">)/,`$1${escape(c.description)}$2`).replace(/(<link rel="canonical" href=")[^"]*(">)/,`$1https://elvarins.com/collections/${slug}$2`).replace(/(<meta property="og:title" content=")[^"]*(">)/,`$1${escape(c.name)} | Elvarins$2`).replace(/(<meta property="og:description" content=")[^"]*(">)/,`$1${escape(c.description)}$2`).replace(/(<meta property="og:url" content=")[^"]*(">)/,`$1https://elvarins.com/collections/${slug}$2`);
 page=page.replace(/<section class="hero">[\s\S]*?<\/section>/,`<section class="collection-hero"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>${escape(c.name)}</span></nav><span class="eyebrow">Elvarins · ${slug==='pet-supplies'?'Pet supplies':'Toys &amp; collectibles'}</span><h1>${escape(c.name)}</h1><p>${escape(c.description)}</p></section>`);
 page=page.replace(/<section[^>]*class="[^"]*home-only[^"]*"[^>]*>[\s\S]*?<\/section>/g,'');
 page=page.replace(/<section class="collection-showcase[\s\S]*?<\/section>/,'');
 page=page.replace(/<article class="product-card" data-sku="([^"]+)">[\s\S]*?<\/article>/g,(all,sku)=>subset.some(p=>p.sku===sku)?all:'');
 if(slug==='pet-supplies'){
  page=page.replace(/<div class="product-grid" id="product-grid">\s*<\/div>/,'<div class="product-grid" id="product-grid">'+subset.map(card).join('')+'</div>');
  page=page.replace('<h2>Explore all products</h2>','<h2>Pet Supplies</h2>');
  page=page.replace('Find a character you love, a figure for your display or something for play.','Find the right toy for your companion, with clear sizing and care guidance.');
  page=page.replace(/<nav[^>]+aria-label="Toy collections"[\s\S]*?<\/nav>/,'');
  page=page.replace(/(<select[^>]+id="brand-filter"[^>]*>)[\s\S]*?<\/select>/,'$1<option value="">All brands</option>'+[...new Set(subset.map(p=>p.brand))].map(b=>'<option>'+escape(b)+'</option>').join('')+'</select>');
  page=page.replace(/(<select[^>]+id="type-filter"[^>]*>)[\s\S]*?<\/select>/,'$1<option value="">All types</option>'+[...new Set(subset.map(p=>p.productType))].map(b=>'<option>'+escape(b)+'</option>').join('')+'</select>');
 }
 page=page.replace(/(<span[^>]*id="result-count"[^>]*>)[^<]*/,'$1'+subset.length+' product'+(subset.length===1?'':'s'));
 page=page.replace(/<script id="catalog-data" type="application\/json">[\s\S]*?<\/script>/,`<script id="catalog-data" type="application/json">${json(subset)}</script>`);
 page=page.replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/,`<script type="application/ld+json">${json({'@context':'https://schema.org','@type':'CollectionPage',name:c.name,description:c.description,url:'https://elvarins.com/collections/'+slug,mainEntity:{'@type':'ItemList',itemListElement:subset.map((p,i)=>({'@type':'ListItem',position:i+1,name:p.title,url:'https://elvarins.com'+p.url}))}})}</script>`);
 page=page.replace('href="/collections/'+slug+'"','aria-current="page" href="/collections/'+slug+'"');
 page=page.replace(/href="#(top|collections|about|contact|shipping|returns|pets|health|privacy)"/g,'href="/#$1"');
 return page;
}

